  1	/**
  2	 * Unit tests for the Notes Collected View (WP-008).
  3	 *
  4	 * Covers all acceptance criteria:
  5	 *   AC1 — Two-panel layout is rendered (.notes-view, .notes-sidebar, .notes-main).
  6	 *   AC2 — Sidebar lists workspaces grouped by project (collapsible <details>).
  7	 *   AC3 — Sidebar items with notes carry the .has-notes class.
  8	 *   AC4 — Clicking a sidebar item for a workspace with a card scrolls to it.
  9	 *   AC5 — Clicking a sidebar item without a card creates a new empty card.
 10	 *   AC6 — Each card has a link to #/projects/:pid/workspaces/:wid.
 11	 *   AC7 — Textarea auto-saves after the 1000 ms debounce with status indicator.
 12	 *   AC8 — Saving empty removes the card and clears the sidebar .has-notes class.
 13	 *   AC9 — On initial load only non-empty note cards are rendered.
 14	 *
 15	 * Run individually with:
 16	 *   node --test 'gui/public/js/views/notes-collected.test.mjs'
 17	 */
 18	
 19	import { test, beforeEach, afterEach } from 'node:test';
 20	import assert from 'node:assert/strict';
 21	import { JSDOM } from 'jsdom';
 22	
 23	// ---------------------------------------------------------------------------
 24	// jsdom setup — install globals before any module is loaded
 25	// ---------------------------------------------------------------------------
 26	
 27	const dom = new JSDOM(
 28	    '<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>',
 29	    { url: 'http://localhost/' },
 30	);
 31	
 32	const { window } = dom;
 33	
 34	globalThis.document    = window.document;
 35	globalThis.window      = window;
 36	globalThis.location    = window.location;
 37	globalThis.HTMLElement = window.HTMLElement;
 38	globalThis.CSS         = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 39	globalThis.Event       = window.Event;
 40	
 41	// ---------------------------------------------------------------------------
 42	// Timer stubs — allow fine-grained debounce control in tests
 43	// ---------------------------------------------------------------------------
 44	
 45	let _pendingDebounce       = null;
 46	let _originalSetTimeout    = null;
 47	let _originalClearTimeout  = null;
 48	/** Map from timer ID → pending callback, for correct clearTimeout semantics. */
 49	const _pendingTimers       = new Map();
 50	
 51	/**
 52	 * Immediately execute the pending debounce callback and await the result.
 53	 */
 54	async function flushDebounce() {
 55	    if (_pendingDebounce) {
 56	        const fn = _pendingDebounce;
 57	        _pendingDebounce = null;
 58	        await fn();
 59	    }
 60	}
 61	
 62	// ---------------------------------------------------------------------------
 63	// Minimal fetch mock (required by api.js import)
 64	// ---------------------------------------------------------------------------
 65	
 66	globalThis.fetch = async () => ({
 67	    status: 200,
 68	    ok: true,
 69	    statusText: 'OK',
 70	    headers: { get: () => 'application/json' },
 71	    json: async () => ({}),
 72	});
 73	
 74	// ---------------------------------------------------------------------------
 75	// Import dependencies and stub API
 76	// ---------------------------------------------------------------------------
 77	
 78	const { api } = await import('../api.js');
 79	
 80	// Stub api.config.notesDisplay.get so notes-collected.js can resolve its
 81	// config fetch without hanging.
 82	if (!api.config) api.config = {};
 83	if (!api.config.notesDisplay) api.config.notesDisplay = {};
 84	api.config.notesDisplay.get = async () => ({});
 85	
 86	/** Calls recorded by api.workspaces.update spy. */
 87	const updateCalls = [];
 88	let updateShouldFail = false;
 89	
 90	const defaultUpdateStub = async (projectId, wid, data) => {
 91	    updateCalls.push({ projectId, wid, data });
 92	    if (updateShouldFail) throw new Error('Storage error');
 93	    return { WorkspaceID: wid };
 94	};
 95	api.workspaces.update = defaultUpdateStub;
 96	
 97	/** Simulated notes response — two projects, three workspaces. */
 98	let notesResponseStub = {
 99	    Projects: [
100	        {

101	            ProjectId:   'proj-a',
102	            ProjectName: 'Project A',
103	            Workspaces: [
104	                { WorkspaceId: 'STABLE', Notes: '' },
105	                { WorkspaceId: 'DEV',    Notes: 'some notes' },
106	            ],
107	        },
108	        {
109	            ProjectId:   'proj-b',
110	            ProjectName: 'Project B',
111	            Workspaces: [
112	                { WorkspaceId: 'STABLE', Notes: '' },
113	            ],
114	        },
115	    ],
116	};
117	api.notes = { list: async () => notesResponseStub };
118	
119	const { renderNotesCollected } = await import('./notes-collected.js');
120	
121	// ---------------------------------------------------------------------------
122	// Helpers
123	// ---------------------------------------------------------------------------
124	
125	const container = window.document.getElementById('app');
126	
127	/**
128	 * Render the notes-collected view and await the async data fetch.
129	 */
130	async function render() {
131	    // Stub setTimeout / clearTimeout so debounce can be flushed synchronously.
132	    _pendingDebounce      = null;
133	    _originalSetTimeout   = globalThis.setTimeout;
134	    _originalClearTimeout = globalThis.clearTimeout;
135	    _pendingTimers.clear();
136	
137	    let _nextTimerId = 2000;
138	    globalThis.setTimeout = (fn, _delay) => {
139	        const id = ++_nextTimerId;
140	        _pendingDebounce = fn;
141	        _pendingTimers.set(id, fn);
142	        return id;
143	    };
144	    globalThis.clearTimeout = (id) => {
145	        if (_pendingTimers.has(id)) {
146	            // Only clear _pendingDebounce when it still refers to this timer's callback.
147	            if (_pendingDebounce === _pendingTimers.get(id)) {
148	                _pendingDebounce = null;
149	            }
150	            _pendingTimers.delete(id);
151	        }
152	    };
153	
154	    // Stub scrollIntoView — not available in jsdom.
155	    const origScrollIntoView = window.HTMLElement.prototype.scrollIntoView;
156	    window.HTMLElement.prototype.scrollIntoView = () => {};
157	
158	    // Stub focus so it does not throw in jsdom.
159	    window.HTMLElement.prototype.focus = function () {};
160	
161	    const result = renderNotesCollected(container, {});
162	    // Let the api.notes.list() promise resolve.
163	    await new Promise((resolve) => _originalSetTimeout(resolve, 0));
164	    await result;
165	
166	    // Restore scrollIntoView if it existed.
167	    if (origScrollIntoView !== undefined) {
168	        window.HTMLElement.prototype.scrollIntoView = origScrollIntoView;
169	    }
170	}
171	
172	function restoreTimers() {
173	    if (_originalSetTimeout)   globalThis.setTimeout   = _originalSetTimeout;
174	    if (_originalClearTimeout) globalThis.clearTimeout = _originalClearTimeout;
175	    _pendingDebounce = null;
176	    _pendingTimers.clear();
177	}
178	
179	function clearContainer() {
180	    while (container.firstChild) container.removeChild(container.firstChild);
181	}
182	
183	// ---------------------------------------------------------------------------
184	// Tests
185	// ---------------------------------------------------------------------------
186	
187	afterEach(() => {
188	    // Always restore the original setTimeout/clearTimeout, even when a test
189	    // assertion fails mid-execution. This prevents subsequent tests from
190	    // inheriting a stale stub.
191	    restoreTimers();
192	});
193	
194	beforeEach(() => {
195	    clearContainer();
196	    updateCalls.length = 0;
197	    updateShouldFail   = false;
198	    api.workspaces.update = defaultUpdateStub;
199	    notesResponseStub = {
200	        Projects: [
201	            {
202	                ProjectId:   'proj-a',
203	                ProjectName: 'Project A',
204	                Workspaces: [
205	                    { WorkspaceId: 'STABLE', Notes: '' },
206	                    { WorkspaceId: 'DEV',    Notes: 'some notes' },
207	                ],
208	            },
209	            {
210	                ProjectId:   'proj-b',
211	                ProjectName: 'Project B',
212	                Workspaces: [
213	                    { WorkspaceId: 'STABLE', Notes: '' },
214	                ],
215	            },
216	        ],
217	    };
218	    api.notes.list = async () => notesResponseStub;
219	});
220	
221	// ---- AC1: Two-panel layout ----
222	
223	test('AC1: renders .notes-view wrapper with .notes-sidebar and .notes-main', async () => {
224	    await render();
225	    const view    = container.querySelector('.notes-view');
226	    const sidebar = container.querySelector('.notes-sidebar');
227	    const main    = container.querySelector('.notes-main');
228	    assert.ok(view,    '.notes-view should be rendered');
229	    assert.ok(sidebar, '.notes-sidebar should be rendered');
230	    assert.ok(main,    '.notes-main should be rendered');
231	});
232	
233	// ---- AC2: Sidebar grouped by project ----
234	
235	test('AC2: sidebar has one collapsible group per project', async () => {
236	    await render();
237	    const groups = container.querySelectorAll('.notes-sidebar-group');
238	    assert.strictEqual(groups.length, 2);
239	});
240	
241	test('AC2: each group contains the correct workspace buttons', async () => {
242	    await render();
243	    const groups = container.querySelectorAll('.notes-sidebar-group');
244	    const firstGroupBtns = groups[0].querySelectorAll('.notes-sidebar-btn');
245	    assert.strictEqual(firstGroupBtns.length, 2, 'proj-a has 2 workspaces');
246	    const secondGroupBtns = groups[1].querySelectorAll('.notes-sidebar-btn');
247	    assert.strictEqual(secondGroupBtns.length, 1, 'proj-b has 1 workspace');
248	});
249	
250	test('AC2: groups are open by default', async () => {
251	    await render();
252	    const groups = container.querySelectorAll('details.notes-sidebar-group');
253	    for (const group of groups) {
254	        assert.strictEqual(group.open, true, 'groups should be open by default');
255	    }
256	});
257	
258	// ---- AC3: Visual distinction for workspaces with notes ----
259	
260	test('AC3: sidebar item for workspace with notes has .has-notes class', async () => {
261	    await render();
262	    const items = container.querySelectorAll('.notes-sidebar-item');
263	    const devItem = Array.from(items).find(
264	        (li) => li.dataset.projectId === 'proj-a' && li.dataset.workspaceId === 'DEV',
265	    );
266	    assert.ok(devItem, 'DEV workspace item should exist in sidebar');
267	    assert.ok(devItem.classList.contains('has-notes'), 'DEV item should have .has-notes');
268	});
269	
270	test('AC3: sidebar item for workspace without notes does NOT have .has-notes class', async () => {
271	    await render();
272	    const items = container.querySelectorAll('.notes-sidebar-item');
273	    const stableItem = Array.from(items).find(
274	        (li) => li.dataset.projectId === 'proj-a' && li.dataset.workspaceId === 'STABLE',
275	    );
276	    assert.ok(stableItem, 'STABLE workspace item should exist in sidebar');
277	    assert.ok(!stableItem.classList.contains('has-notes'), 'STABLE item should NOT have .has-notes');
278	});
279	
280	// ---- AC4: Clicking sidebar item with existing card scrolls to it ----
281	
282	test('AC4: clicking sidebar item for a workspace with a card does not create a duplicate card', async () => {
283	    await render();
284	    // DEV already has a card on initial load.
285	    const cardsBefore = container.querySelectorAll('.notes-card');
286	    const countBefore = cardsBefore.length;
287	
288	    const devBtn = Array.from(container.querySelectorAll('.notes-sidebar-btn')).find(
289	        (btn) => btn.closest('.notes-sidebar-item').dataset.workspaceId === 'DEV',
290	    );
291	    devBtn.click();
292	
293	    const cardsAfter = container.querySelectorAll('.notes-card');
294	    assert.strictEqual(cardsAfter.length, countBefore, 'no duplicate card should be created');
295	});
296	
297	// ---- AC5: Clicking sidebar item without a card creates one ----
298	
299	test('AC5: clicking sidebar item for a workspace without a card creates a new card', async () => {
300	    await render();

301	    const stableBtn = Array.from(container.querySelectorAll('.notes-sidebar-btn')).find(
302	        (btn) => btn.closest('.notes-sidebar-item').dataset.projectId === 'proj-a'
303	            && btn.closest('.notes-sidebar-item').dataset.workspaceId === 'STABLE',
304	    );
305	    stableBtn.click();
306	
307	    const stableCard = Array.from(container.querySelectorAll('.notes-card')).find(
308	        (c) => c.dataset.projectId === 'proj-a' && c.dataset.workspaceId === 'STABLE',
309	    );
310	    assert.ok(stableCard, 'a new card for STABLE should be created');
311	});
312	
313	test('AC5: new card textarea is empty and present', async () => {
314	    await render();
315	    const stableBtn = Array.from(container.querySelectorAll('.notes-sidebar-btn')).find(
316	        (btn) => btn.closest('.notes-sidebar-item').dataset.projectId === 'proj-a'
317	            && btn.closest('.notes-sidebar-item').dataset.workspaceId === 'STABLE',
318	    );
319	    stableBtn.click();
320	
321	    const stableCard = Array.from(container.querySelectorAll('.notes-card')).find(
322	        (c) => c.dataset.projectId === 'proj-a' && c.dataset.workspaceId === 'STABLE',
323	    );
324	    const ta = stableCard.querySelector('.notes-card-textarea');
325	    assert.ok(ta, 'card should contain a textarea');
326	    assert.strictEqual(ta.value, '', 'new card textarea should be empty');
327	});
328	
329	// ---- AC6: Card header link to workspace detail ----
330	
331	test('AC6: card header contains a link to the workspace detail view', async () => {
332	    await render();
333	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
334	        (c) => c.dataset.projectId === 'proj-a' && c.dataset.workspaceId === 'DEV',
335	    );
336	    assert.ok(devCard, 'DEV card should be rendered');
337	
338	    const link = devCard.querySelector('a.notes-card-ws-link');
339	    assert.ok(link, 'card should contain a .notes-card-ws-link anchor');
340	    assert.ok(
341	        link.href.includes('/projects/proj-a/workspaces/DEV'),
342	        'link href should point to workspace detail',
343	    );
344	});
345	
346	// ---- AC7: Auto-save with status indicator ----
347	
348	test('AC7: typing triggers api.workspaces.update after the debounce', async () => {
349	    await render();
350	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
351	        (c) => c.dataset.workspaceId === 'DEV',
352	    );
353	    const ta = devCard.querySelector('.notes-card-textarea');
354	
355	    ta.value = 'updated notes';
356	    ta.dispatchEvent(new window.Event('input'));
357	
358	    // Debounce has not fired yet.
359	    assert.strictEqual(updateCalls.length, 0);
360	
361	    await flushDebounce();
362	
363	    assert.strictEqual(updateCalls.length, 1);
364	    assert.strictEqual(updateCalls[0].projectId, 'proj-a');
365	    assert.strictEqual(updateCalls[0].wid, 'DEV');
366	    assert.deepStrictEqual(updateCalls[0].data, { notes: 'updated notes' });
367	});
368	
369	test('AC7: status indicator shows "Saving…" while save is in flight', async () => {
370	    let resolveUpdate;
371	    api.workspaces.update = async (_pid, _wid, _data) => {
372	        updateCalls.push({ data: _data });
373	        await new Promise((resolve) => { resolveUpdate = resolve; });
374	        return {};
375	    };
376	
377	    await render();
378	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
379	        (c) => c.dataset.workspaceId === 'DEV',
380	    );
381	    const ta       = devCard.querySelector('.notes-card-textarea');
382	    const statusEl = devCard.querySelector('.notes-card-status');
383	
384	    ta.value = 'in flight';
385	    ta.dispatchEvent(new window.Event('input'));
386	
387	    // Fire the debounce but do NOT await — let it block on the held update.
388	    const savedPending = _pendingDebounce;
389	    _pendingDebounce = null;
390	    savedPending(); // not awaited intentionally
391	
392	    // One tick so the async handler reaches the first await (api call).
393	    await new Promise((resolve) => _originalSetTimeout(resolve, 0));
394	
395	    assert.strictEqual(statusEl.hidden, false);
396	    assert.strictEqual(statusEl.textContent, 'Saving\u2026');
397	
398	    resolveUpdate();
399	    await new Promise((resolve) => _originalSetTimeout(resolve, 0));
400	});
401	
402	test('AC7: status indicator shows "Saved" after a successful save', async () => {
403	    await render();
404	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
405	        (c) => c.dataset.workspaceId === 'DEV',
406	    );
407	    const ta       = devCard.querySelector('.notes-card-textarea');
408	    const statusEl = devCard.querySelector('.notes-card-status');
409	
410	    ta.value = 'final notes';
411	    ta.dispatchEvent(new window.Event('input'));
412	    await flushDebounce();
413	
414	    assert.strictEqual(statusEl.hidden, false);
415	    assert.strictEqual(statusEl.textContent, 'Saved');
416	});
417	
418	test('AC7: status indicator shows "Save failed." when api call rejects', async () => {
419	    updateShouldFail = true;
420	    await render();
421	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
422	        (c) => c.dataset.workspaceId === 'DEV',
423	    );
424	    const ta       = devCard.querySelector('.notes-card-textarea');
425	    const statusEl = devCard.querySelector('.notes-card-status');
426	
427	    ta.value = 'will fail';
428	    ta.dispatchEvent(new window.Event('input'));
429	    await flushDebounce();
430	
431	    assert.strictEqual(statusEl.textContent, 'Save failed.');
432	});
433	
434	// ---- AC8: Saving empty removes card and clears sidebar indicator ----
435	
436	test('AC8: saving empty text removes the card from the main panel', async () => {
437	    await render();
438	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
439	        (c) => c.dataset.workspaceId === 'DEV',
440	    );
441	    assert.ok(devCard, 'DEV card should be present before save');
442	
443	    const ta = devCard.querySelector('.notes-card-textarea');
444	    ta.value = '';
445	    ta.dispatchEvent(new window.Event('input'));
446	    await flushDebounce();
447	
448	    const cardAfter = Array.from(container.querySelectorAll('.notes-card')).find(
449	        (c) => c.dataset.workspaceId === 'DEV',
450	    );
451	    assert.strictEqual(cardAfter, undefined, 'DEV card should be removed after empty save');
452	});
453	
454	test('AC8: saving empty clears .has-notes on the sidebar item', async () => {
455	    await render();
456	    const devCard = Array.from(container.querySelectorAll('.notes-card')).find(
457	        (c) => c.dataset.workspaceId === 'DEV',
458	    );
459	    const ta = devCard.querySelector('.notes-card-textarea');
460	    ta.value = '';
461	    ta.dispatchEvent(new window.Event('input'));
462	    await flushDebounce();
463	
464	    const devItem = Array.from(container.querySelectorAll('.notes-sidebar-item')).find(
465	        (li) => li.dataset.projectId === 'proj-a' && li.dataset.workspaceId === 'DEV',
466	    );
467	    assert.ok(devItem, 'DEV sidebar item should still exist');
468	    assert.ok(!devItem.classList.contains('has-notes'), '.has-notes should be removed from sidebar item');
469	});
470	
471	test('AC8: empty-state message appears when all cards are removed', async () => {
472	    // Only one workspace has notes.
473	    notesResponseStub = {
474	        Projects: [
475	            {
476	                ProjectId:   'single',
477	                ProjectName: 'Single',
478	                Workspaces: [{ WorkspaceId: 'WS-1', Notes: 'hello' }],
479	            },
480	        ],
481	    };
482	    await render();
483	
484	    const card = container.querySelector('.notes-card');
485	    assert.ok(card, 'initial card should be present');
486	
487	    const ta = card.querySelector('.notes-card-textarea');
488	    ta.value = '';
489	    ta.dispatchEvent(new window.Event('input'));
490	    await flushDebounce();
491	
492	    const empty = container.querySelector('.notes-empty-state');
493	    assert.ok(empty, '.notes-empty-state should appear after last card is removed');
494	});
495	
496	// ---- AC9: Initial load only shows non-empty cards ----
497	
498	test('AC9: on initial load, only non-empty notes produce cards', async () => {
499	    await render();
500	    const cards = container.querySelectorAll('.notes-card');

501	    // Only proj-a/DEV has notes ('some notes').
502	    assert.strictEqual(cards.length, 1, 'only one card should be rendered initially');
503	    assert.strictEqual(cards[0].dataset.projectId,   'proj-a');
504	    assert.strictEqual(cards[0].dataset.workspaceId, 'DEV');
505	});
506	
507	test('AC9: empty-state message shown when no workspaces have notes on load', async () => {
508	    notesResponseStub = {
509	        Projects: [
510	            {
511	                ProjectId:   'empty-proj',
512	                ProjectName: 'Empty Proj',
513	                Workspaces: [{ WorkspaceId: 'STABLE', Notes: '' }],
514	            },
515	        ],
516	    };
517	    await render();
518	
519	    const cards = container.querySelectorAll('.notes-card');
520	    assert.strictEqual(cards.length, 0, 'no cards should render when all notes are empty');
521	
522	    const empty = container.querySelector('.notes-empty-state');
523	    assert.ok(empty, '.notes-empty-state should be shown');
524	});

